import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    x = int(data[1])
    arr = list(map(int, data[2:2+n]))

    if n == 0:
        print("-1")
        return

    val_to_idx = {}
    for i in range(n):
        if arr[i] != 0:
            if x % arr[i] == 0:
                complement = x // arr[i]
                if complement in val_to_idx:
                    idx1 = val_to_idx[complement]
                    idx2 = i
                    if idx1 < idx2:
                        print(f"{idx1 + 1} {idx2 + 1}")
                    else:
                        print(f"{idx2 + 1} {idx1 + 1}")
                    return
            if arr[i] not in val_to_idx:
                val_to_idx[arr[i]] = i

    if x == 0:
        for i in range(n):
            if arr[i] == 0:
                for j in range(i + 1, n):
                    if arr[j] == 0:
                        print(f"{i + 1} {j + 1}")
                        return

    print("-1")

if __name__ == "__main__":
    main()
